import test from 'node:test';
import assert from 'node:assert/strict';
import {validateEdit,registerTools} from './webmcp.js';
test('malformed map edits fail before touching the app',()=>{for(const input of [null,[],{}, {action:'set_failure',nodeId:'x',failed:'true'},{action:'set_failure',nodeId:'x',failed:true,sourceId:'y'},{action:'connect',sourceId:'a'},{action:'disconnect',sourceId:'a',targetId:'b',unknown:1}])assert.throws(()=>validateEdit(input));});
test('registered tools call the visible actions and enforce schemas',()=>{const registered=[];let calls=0;const api={getState:()=>({calls}),connect:()=>calls++,disconnect:()=>calls++,setFailure:()=>calls++};const stop=registerTools(api,{documentRef:{modelContext:{registerTool:(tool,options)=>registered.push({tool,options})}},navigatorRef:null});assert.equal(registered.length,2);assert.deepEqual(registered[0].tool.execute({}),{calls:0});assert.throws(()=>registered[0].tool.execute({unknown:true}));assert.throws(()=>registered[1].tool.execute({action:'connect',sourceId:'a'}));assert.equal(calls,0);assert.deepEqual(registered[1].tool.execute({action:'set_failure',nodeId:'a',failed:true}),{calls:1});stop();assert.ok(registered.every(x=>x.options.signal.aborted));});
test('missing support and synchronous/asynchronous registration failures are handled',async()=>{assert.doesNotThrow(()=>registerTools({}, {documentRef:null,navigatorRef:null})());const errors=[];let i=0;registerTools({}, {documentRef:{modelContext:{registerTool(){if(i++===0)throw Error('sync');return Promise.reject(Error('async'));}}},navigatorRef:null,reportError:e=>errors.push(e.message)});await Promise.resolve();assert.deepEqual(errors,['sync','async']);});
